#!/usr/bin/env bash
# Runs the API-coverage audit scenes (tests/audit_scenes/*.ops, generated by
# tools/oracle/audit_scenes.py) through the real C++ libavoid and writes the
# goldens tests/audit_scenes/golden/<scene>{-N,-final}.txt, .exit, .stdout.
#
#   tools/oracle/audit_scenes.sh [--regen [COUNT]] [scene ...]
#
# Two builds of a copy of the vendored sources, both with the
# tools/oracle/build.sh patches (%.17g diagram dumps, junction positions,
# final dump from ~Router), -DNDEBUG (the reference is upstream's release
# build; the port does not port asserts upstream violates on valid input,
# src/avoid/router.rs "Asserts") and -fno-access-control:
#  * asan: glibc malloc + AddressSanitizer.  A scene on which upstream reads
#    freed memory, dereferences null or crashes has undefined upstream
#    behaviour and is dropped (its golden removed; tests/audit_scenes.rs
#    skips it and reports it).
#  * rel: -O2 -ffp-contract=off with the bump allocator
#    (tools/oracle/bump_alloc.cpp: pointer order == allocation order, the
#    port's model).  This run produces the goldens.
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
BUILD="$ROOT/target/audit-oracle"
SCENES="$ROOT/tests/audit_scenes"
GOLDEN="$SCENES/golden"
JOBS="${AUDIT_JOBS:-4}"
if [ "${1:-}" = "--regen" ]; then
  shift
  n=""; if [ $# -gt 0 ] && [[ "$1" =~ ^[0-9]+$ ]]; then n="$1"; shift; fi
  rm -f "$SCENES"/audit_*.ops
  python3 "$ROOT/tools/oracle/audit_scenes.py" $n
fi
mkdir -p "$BUILD/run" "$GOLDEN"

ORACLE_LIB_ONLY=1 "$ROOT/tools/oracle/build.sh" > /dev/null
build_lib() {  # dir flags...
  local d="$1"; shift
  mkdir -p "$d/libavoid"
  cp -u "$ROOT/target/oracle/libavoid/"*.cpp "$ROOT/target/oracle/libavoid/"*.h "$d/libavoid/"
  local objs=() f o
  for f in "$d"/libavoid/*.cpp; do
    o="${f%.cpp}.o"; objs+=("$o")
    if [ ! -f "$o" ] || [ "$f" -nt "$o" ]; then g++ "$@" -I"$d" -c "$f" -o "$o" & fi
  done
  wait
  rm -f "$d/lib.a"; ar rcs "$d/lib.a" "${objs[@]}"
}
REL=(-O2 -std=c++11 -w -DNDEBUG -ffp-contract=off -fno-access-control)
ASAN=(-O1 -g -std=c++11 -w -DNDEBUG -fno-access-control -fsanitize=address)
build_lib "$BUILD/rel" "${REL[@]}"
build_lib "$BUILD/asan" "${ASAN[@]}"
g++ "${REL[@]}" -I"$BUILD/rel" -c "$ROOT/tools/oracle/bump_alloc.cpp" -o "$BUILD/rel/bump_alloc.o"

if [ $# -gt 0 ]; then names=("$@"); else
  names=(); for f in "$SCENES"/audit_*.ops; do names+=("$(basename "$f" .ops)"); done
fi

run_one() {
  local n="$1" d="$BUILD/run/$1"
  rm -rf "$d"; mkdir -p "$d/output" "$d/asan/output"
  rm -f "$GOLDEN/$n"-*.txt "$GOLDEN/$n".exit "$GOLDEN/$n".stdout
  python3 "$ROOT/tools/fixtures/convert.py" --emit-cpp "$SCENES/$n.ops" "$d/$n.cpp" 2> "$d/emit.log" \
    || { echo "EMIT-FAIL $n: $(head -c 200 "$d/emit.log")"; return; }
  g++ "${ASAN[@]}" -I"$BUILD/asan" "$d/$n.cpp" "$BUILD/asan/lib.a" -o "$d/$n-asan" 2> "$d/compile.log" \
    && g++ "${REL[@]}" -I"$BUILD/rel" "$d/$n.cpp" "$BUILD/rel/bump_alloc.o" "$BUILD/rel/lib.a" -o "$d/$n" 2>> "$d/compile.log" \
    || { echo "COMPILE-FAIL $n: $(grep -m2 error "$d/compile.log")"; return; }
  local code=0
  (cd "$d/asan" && ASAN_OPTIONS=detect_leaks=0 ORACLE_FINAL="output/$n" timeout -s KILL 120 "../$n-asan" \
    > /dev/null 2> "$d/asan.log") || code=$?
  if [ "$code" -ne 0 ]; then
    echo "DROP $n (undefined upstream: asan exit $code: $(grep -m1 -E 'ERROR: AddressSanitizer|SUMMARY' "$d/asan.log" | cut -c1-120))"
    return
  fi
  (cd "$d" && ORACLE_FINAL="output/$n" timeout -s KILL 120 "./$n" > "$d/stdout" 2>/dev/null) || code=$?
  if [ "$code" -ne 0 ]; then echo "DROP $n (bump build exit $code)"; return; fi
  cp "$d"/output/*.txt "$GOLDEN/"
  echo "$code" > "$GOLDEN/$n.exit"
  cp "$d/stdout" "$GOLDEN/$n.stdout"
  echo "OK $n"
}
for n in "${names[@]}"; do
  run_one "$n" > "$BUILD/run/$n.result" &
  while [ "$(jobs -r | wc -l)" -ge "$JOBS" ]; do sleep 0.1; done
done
wait
cat "$BUILD"/run/*.result | sort > "$BUILD/summary.txt"
grep -v '^OK' "$BUILD/summary.txt" || true
echo "audit scenes: $(grep -c '^OK' "$BUILD/summary.txt") ok, $(grep -vc '^OK' "$BUILD/summary.txt") not ok"
